(() => {
  const btn = document.querySelector('#readBtn');
  if (!btn) return;
  const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
  const clickableTerms = ['紫微斗數','八字','四柱','日主','月令','十神','流運','命宮','官祿宮','財帛宮','四化','奇門遁甲','九宮','八門','九星','八神','值符','值使','印度占星','Lagna','Moon sign','Bhava','Nakshatra','Dasha','梅花易數','本卦','互卦','變卦','動爻','體用','小六壬','六神','易經','卦辭','爻位'];
  const linkTerms = value => clickableTerms.sort((a,b)=>b.length-a.length).reduce((out, term) => out.replaceAll(term, `<button class="rich-term" data-term="${term}">${term}</button>`), escape(value));
  const copy = {
    '紫微斗數': [
      ['命宮：你點樣出場', '命宮係人生主軸；要先看主星，再看同宮輔星，先知道你係靠主導、協調、冒險定累積去做決定。'],
      ['官祿宮：工作點樣落地', '官祿宮對應職責、上司、專業位置同壓力來源。星曜多唔代表一定好或壞，要連同亮度、會照及流限先判斷。'],
      ['財帛宮：能力點樣變回報', '財帛宮睇收入模式、資源管理及風險承受。問揀工時，重點係份工有冇清晰權限、可量化成果及穩定回饋。'],
      ['四化：邊度有推力／卡點', '化祿係資源，化權係推動力，化科係可見度，化忌係卡位；四化係提示，不係單獨決定吉凶。']
    ],
    '八字': [
      ['四柱：先看完整底盤', '年柱看早年與背景，月柱看成長環境及工作基礎，日柱看本人核心，時柱看後期發展與長期目標。'],
      ['日主：你用咩方式承受事情', '日主係日干，代表你本人。要連同月令、根氣、透干及五行分布判斷強弱，唔可以只見一個字就下結論。'],
      ['十神：工作與財務語言', '十神將資源、責任、輸出、財務及同伴分類。揀工作時，要比較責任是否有資源承托，而唔係只比較人工。'],
      ['流運：幾時適合郁', '大運講十年方向，流年、流月、流日講當期節奏；佢哋只提供時間提示，最後要用合約、公司狀況及面試證據覆核。']
    ],
    '奇門遁甲': [
      ['九宮：事情落喺邊個位置', '九宮將人物、方向、資源及阻力分開，先定位問題用神，再看該宮內的門、星、神有冇互相支持。'],
      ['八門：事情點樣行', '開門偏向機會與對外，生門偏向資源與收益，杜門偏向準備與收斂；門係行動通道，不是簡單吉凶標籤。'],
      ['九星八神：能力同暗線', '九星講思考、能力及事件質地，八神講氣勢、心理及隱性因素；要連同值符、值使及空亡交叉核對。'],
      ['值符值使：主軸與落地方法', '值符係全局核心，值使係事情落地方式。問工作時，先問權責、第一個交付及決策權，將盤象變成可驗證問題。']
    ],
    '印度占星': [
      ['Lagna：你如何進入世界', 'Lagna 是上升點，描述外在反應、出場方式及人生開局；要連同上升主星落宮一齊睇，唔係只看星座名稱。'],
      ['Moon sign：你內在需要咩', '月亮星座反映情緒反應、習慣及安全感。工作選擇上，會影響你對節奏、團隊氣氛及穩定程度嘅要求。'],
      ['Bhava：行星影響邊個生活範圍', 'Bhava 將行星功能放入工作、財務、感情等生活領域；同一粒星落唔同宮，實際表現可以完全唔同。'],
      ['Nakshatra／Dasha：細分時間', 'Nakshatra 細分月亮心理模式，Vimshottari Dasha 用行星主周期安排時間層；精確餘額仍要由完整星曆覆核。']
    ],
    '梅花易數': [
      ['本卦：眼前發生緊咩', '本卦係問題表面結構，先描述現況，唔係直接宣布結果。問工作時先核對職責、資源及對方承諾。'],
      ['互卦：真正卡住嘅內層', '互卦睇事情中段運作，常用來找出支持不足、溝通斷層或你自己未承認嘅取捨。'],
      ['變卦：下一階段會點變', '變卦係動爻之後嘅方向，係趨勢提示而非保證；如果條件未補齊，應先試行再投入。'],
      ['體用：你同環境點互動', '體代表自身， 用代表事情與環境；以生剋看互動，最後要翻譯成一個 24 小時內可以驗證嘅行動。']
    ],
    '小六壬': [
      ['六神：當下節奏', '大安、留連、速喜、赤口、小吉、空亡係六種事情節奏；重點係快慢、阻力、消息及是否要等待。'],
      ['落宮：事情落點', '落宮幫你知道今次問題主要落在自己、對方、資源或外在環境；唔可以脫離提問內容單獨解。'],
      ['課象：將象意翻譯成現實', '問工作時，六神唔直接等於錄取或失敗，而係提示你應立即追問、暫緩、避開衝突或補資料。'],
      ['行動：只留一個可驗證步驟', '今日先完成一件可以核對嘅事，例如問清楚試用期考核、匯報線及工作時間，再用答案修正判斷。']
    ],
    '易經': [
      ['本卦：你站喺邊個位置', '本卦講目前結構及處境；卦名係摘要，真正解讀要連同卦辭、爻位及你問緊嘅事情。'],
      ['互卦：事情內部運作', '互卦提示中段因素，例如資源、關係、制度或心理壓力；用來找出表面問題下面嘅真正條件。'],
      ['變卦：由而家走向邊度', '變卦描述變化後可能形成嘅方向，唔係命定結果；要配合動爻先知道邊一點需要先處理。'],
      ['卦爻：下一步應守定應變', '爻位將抽象卦象落到事件階段。問工作時，先判斷係應觀察、試行、談判，定係設定退出線。']
    ],
    '綜合解讀': [
      ['第一層：出生命盤', '八字、紫微及印度占星先提供長期傾向，回答你慣用咩方式做事、需要咩資源及最容易失衡嘅位置。'],
      ['第二層：當下卦局', '梅花、掐指一算、奇門及易經處理眼前事件，回答目前阻力、節奏、方向及應先做咩。'],
      ['第三層：互相核對', '如果命盤同卦局都指向清晰權責、先試後定，就可列為較強假設；矛盾時以現實證據及可控風險優先。'],
      ['最後落地：一個決定規則', '將工作選項按上司清晰度、實際權限、收入穩定、學習空間及 90 日成果各評 1 至 5 分，低分先補資料。']
    ]
  };
  const render = () => {
    const host = document.querySelector('#oracleNarrativeResult');
    const method = document.querySelector('.method.active')?.dataset.name;
    if (!host || !method || !copy[method]) return;
    const grid = host.querySelector('.rich-grid');
    if (!grid) return;
    grid.innerHTML = copy[method].map((item, i) => `<section class="rich-block is-revealed"><span class="rich-num">0${i + 1}</span><div><h4>${linkTerms(item[0])}</h4><p>${linkTerms(item[1])}</p></div></section>`).join('');
    host.querySelectorAll('.rich-term').forEach(term => term.addEventListener('click', () => {
      const drawer = host.querySelector('#richTermDrawer');
      if (!drawer) return;
      drawer.innerHTML = `<b>${term.dataset.term}</b><span>呢個術語要放返入今次盤面、宮位／卦位、時間層同你條問題一齊睇，唔可以單獨當成吉凶答案。</span>`;
      drawer.classList.add('is-active');
    }));
  };
  btn.addEventListener('click', () => setTimeout(render, 1800));
})();
